import { ResizableBox } from '@wordpress/components';
import { useState, useEffect } from '@wordpress/element';
import type { CSSProperties, PointerEvent } from 'react';
import { useBlockElement } from '../block-list/use-block-props/use-block-refs';
import BlockPopoverCover from '../block-popover/cover';
import { getComputedCSS, getGridTracks, getClosestTrack } from './utils';
import type {
	GridItemResizerInnerProps,
	GridItemResizerProps,
	GridItemResizerSides,
} from './types';

export function GridItemResizer( {
	clientId,
	bounds,
	onChange,
	parentLayout,
}: GridItemResizerProps ) {
	// Block wrappers are HTML elements.
	const blockElement = useBlockElement( clientId ) as HTMLElement | null;
	const rootBlockElement = blockElement?.parentElement;
	const { isManualPlacement } = parentLayout;

	if ( ! blockElement || ! rootBlockElement ) {
		return null;
	}

	return (
		<GridItemResizerInner
			clientId={ clientId }
			bounds={ bounds }
			blockElement={ blockElement }
			rootBlockElement={ rootBlockElement }
			onChange={ onChange }
			isManualGrid={
				isManualPlacement &&
				window.__experimentalEnableGridInteractivity
			}
		/>
	);
}

function GridItemResizerInner( {
	clientId,
	bounds,
	blockElement,
	rootBlockElement,
	onChange,
	isManualGrid,
}: GridItemResizerInnerProps ) {
	const [ resizeDirection, setResizeDirection ] = useState< string | null >(
		null
	);
	const [ enableSide, setEnableSide ] = useState< GridItemResizerSides >( {
		top: false,
		bottom: false,
		left: false,
		right: false,
	} );

	useEffect( () => {
		// In a manual grid every side is always available: a side on the
		// grid's edge can still shrink the block, and the resize is kept
		// inside the grid by its bounds. Checking the edges here would also
		// go stale when the block moves without changing size.
		if ( isManualGrid ) {
			setEnableSide( {
				top: true,
				bottom: true,
				left: true,
				right: true,
			} );
			return;
		}
		const observer = new window.ResizeObserver( () => {
			const blockClientRect = blockElement.getBoundingClientRect();
			const rootBlockClientRect =
				rootBlockElement.getBoundingClientRect();

			const topAvailable = blockClientRect.top > rootBlockClientRect.top;
			const bottomAvailable =
				blockClientRect.bottom < rootBlockClientRect.bottom;
			const leftAvailable =
				blockClientRect.left > rootBlockClientRect.left;
			const rightAvailable =
				blockClientRect.right < rootBlockClientRect.right;

			setEnableSide( {
				top: ! bottomAvailable && topAvailable,
				bottom: bottomAvailable,
				left: ! rightAvailable && leftAvailable,
				right: rightAvailable,
			} );
		} );
		observer.observe( blockElement );
		return () => observer.disconnect();
	}, [ blockElement, rootBlockElement, isManualGrid ] );

	const justification: Record< string, string > = {
		right: 'left',
		left: 'right',
	};

	const alignment: Record< string, string > = {
		top: 'flex-end',
		bottom: 'flex-start',
	};

	// A `null` direction, while not resizing, matches no key.
	const styles: CSSProperties = {
		display: 'flex',
		justifyContent: 'center',
		alignItems: 'center',
		...( justification[ resizeDirection as string ] && {
			justifyContent: justification[ resizeDirection as string ],
		} ),
		...( alignment[ resizeDirection as string ] && {
			alignItems: alignment[ resizeDirection as string ],
		} ),
	};

	return (
		<BlockPopoverCover
			className="block-editor-grid-item-resizer"
			clientId={ clientId }
			__unstablePopoverSlot="__unstable-block-tools-after"
			additionalStyles={ styles }
		>
			<ResizableBox
				className="block-editor-grid-item-resizer__box"
				size={ {
					width: '100%',
					height: '100%',
				} }
				enable={ {
					bottom: enableSide.bottom,
					bottomLeft: false,
					bottomRight: false,
					left: enableSide.left,
					right: enableSide.right,
					top: enableSide.top,
					topLeft: false,
					topRight: false,
				} }
				bounds={ bounds }
				boundsByDirection
				// @ts-expect-error ResizableBox passes DOM event props to its element without typing them.
				onPointerDown={ ( { target, pointerId }: PointerEvent ) => {
					/*
					 * Captures the pointer to avoid hiccups while dragging over objects
					 * like iframes and ensures that the event to end the drag is
					 * captured by the target (resize handle) whether or not it’s under
					 * the pointer.
					 */
					// The resize handle receives the pointer.
					( target as Element ).setPointerCapture( pointerId );
				} }
				onResizeStart={ ( event, direction ) => {
					/*
					 * The container justification and alignment need to be set
					 * according to the direction the resizer is being dragged in,
					 * so that it resizes in the right direction.
					 */
					setResizeDirection( direction );
				} }
				onResizeStop={ ( event, direction, boxElement ) => {
					const columnGap = parseFloat(
						getComputedCSS( rootBlockElement, 'column-gap' )
					);
					const rowGap = parseFloat(
						getComputedCSS( rootBlockElement, 'row-gap' )
					);
					const gridColumnTracks = getGridTracks(
						getComputedCSS(
							rootBlockElement,
							'grid-template-columns'
						),
						columnGap
					);
					const gridRowTracks = getGridTracks(
						getComputedCSS(
							rootBlockElement,
							'grid-template-rows'
						),
						rowGap
					);
					const rect = new window.DOMRect(
						blockElement.offsetLeft + boxElement.offsetLeft,
						blockElement.offsetTop + boxElement.offsetTop,
						boxElement.offsetWidth,
						boxElement.offsetHeight
					);
					const columnStart =
						getClosestTrack( gridColumnTracks, rect.left ) + 1;
					const rowStart =
						getClosestTrack( gridRowTracks, rect.top ) + 1;
					const columnEnd =
						getClosestTrack( gridColumnTracks, rect.right, 'end' ) +
						1;
					const rowEnd =
						getClosestTrack( gridRowTracks, rect.bottom, 'end' ) +
						1;
					onChange( {
						columnSpan: columnEnd - columnStart + 1,
						rowSpan: rowEnd - rowStart + 1,
						columnStart: isManualGrid ? columnStart : undefined,
						rowStart: isManualGrid ? rowStart : undefined,
					} );
				} }
			/>
		</BlockPopoverCover>
	);
}
